function syncActivityVisuals(){
 for(const [previous,g]of [...chests]){const current=world.world.chests.find(c=>c.id===previous.id);if(current&&current!==previous){chests.delete(previous);chests.set(current,g);g.position.set(current.x,0,current.z)}}
 for(const [c,g]of chests){if(!world.world.chests.includes(c)){scene.remove(g);chests.delete(c)}else g.visible=!(c.opened&&['apothecary','garden'].includes(c.type));if(c.opened&&c.type==='synthesis')g.scale.setScalar(.8)}
 for(const c of world.world.chests)if(!chests.has(c)){
  const g=new THREE.Group();g.position.set(c.x,0,c.z);
  if(c.type==='synthesis')mesh(new THREE.SphereGeometry(1.2,16,12),materials.darkStone,0,1.25,0,1,1,1,g);
  else if(c.type==='pond'){const pond=mesh(new THREE.CylinderGeometry(2,2,.12,24),new THREE.MeshBasicMaterial({color:0x59a9d0}),0,.06,0,1,1,1,g);pond.castShadow=false}
  else if(c.type==='garden'){box(materials.wood,0,.08,0,1.6,.16,1.6,g);for(let j=0;j<3;j++)mesh(crownGeo,materials.leaf,0,.3,c.z*0+j*.4-.4,.25,.3,.25,g)}
  else{box(materials.wood,0,.8,0,1.4,1.6,1.4,g);mesh(new THREE.ConeGeometry(1.3,.8,4),materials.darkStone,0,2,0,1,1,1,g)}
  scene.add(g);chests.set(c,g);
 }
}
function hasLootMovementInput(){return Math.hypot(world.input.x,world.input.z)>.05||MOVEMENT_KEYS.some(code=>keys.has(code))}
