function lootKind(entry){if(entry.type==='pond')return 'pond';if(entry.type==='garden')return 'garden';if(entry.type==='synthesis')return 'synthesis';if(entry.type==='bot')return 'bot';return entry.kind==='chest'?(entry.type==='white'?'white':'chest'):'monster'}
